beforeExample:
import static org.junit.Assert.assertEquals;

class MyTest {
    void testMethod() {
        double expected = 1.0;
        double actual = 1.0;
        assertEquals("message", expected, actual);
    }
}

afterExample:
import static org.junit.Assert.assertEquals;

class MyTest {
    void testMethod() {
        double expected = 1.0;
        double actual = 1.0;
        assertEquals("message", expected, actual, 0);
    }
}

negativeExample:
import static org.junit.Assert.assertEquals;

class MyTest {
    void testIntMethod() {
        int expected = 1;
        int actual = 1;
        assertEquals("message", expected, actual); // Should not match, applies only to doubles
    }
    void testFloatMethod() {
        float expected = 1.0f;
        float actual = 1.0f;
        assertEquals("message", expected, actual); // Should not match, applies only to doubles
    }
    void testDeltaAlreadyPresent() {
        double expected = 1.0;
        double actual = 1.0;
        assertEquals("message", expected, actual, 0.001); // Already has delta (different arity)
    }
}
